{
  "version": 1,
  "id": "cisa_kev",
  "name": "CISA Known Exploited Vulnerabilities (live)",
  "request": {
    "method": "GET",
    "url": "https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json",
    "timeout_seconds": 20
  },
  "auth": {
    "type": "none"
  },
  "items_path": "vulnerabilities",
  "pagination": {
    "type": "none"
  },
  "schedule": {
    "enabled": false,
    "interval_seconds": 86400
  },
  "destination": {
    "class": "vulnerability_finding",
    "mapping": {
      "finding_info.uid": {
        "path": "cveID",
        "required": true,
        "transform": "trim"
      },
      "finding_info.title": {
        "path": "vulnerabilityName",
        "required": true,
        "transform": "trim"
      },
      "finding_info.desc": {
        "path": "shortDescription",
        "transform": "string"
      },
      "time": {
        "path": "dateAdded",
        "required": true,
        "transform": "datetime",
        "format": "2006-01-02",
        "timezone": "UTC"
      },
      "vulnerabilities.0.cve.uid": {
        "path": "cveID",
        "required": true,
        "transform": "trim"
      },
      "vulnerabilities.0.title": {
        "path": "vulnerabilityName",
        "transform": "trim"
      },
      "vulnerabilities.0.desc": {
        "path": "shortDescription",
        "transform": "string"
      },
      "vulnerabilities.0.vendor_name": {
        "path": "vendorProject",
        "transform": "trim"
      },
      "vulnerabilities.0.is_exploit_available": {
        "constant": true
      },
      "vulnerabilities.0.remediation.desc": {
        "path": "requiredAction",
        "transform": "string"
      },
      "vulnerabilities.0.cwe.uid": {
        "path": "cwes.0",
        "transform": "trim"
      },
      "metadata.product.name": {
        "constant": "Known Exploited Vulnerabilities Catalog"
      },
      "metadata.product.vendor_name": {
        "constant": "CISA"
      },
      "unmapped.product": {
        "path": "product",
        "transform": "trim"
      },
      "unmapped.ransomware_use": {
        "path": "knownRansomwareCampaignUse",
        "transform": "string"
      },
      "unmapped.due_date": {
        "path": "dueDate",
        "transform": "string"
      }
    }
  },
  "limits": {
    "max_pages": 1,
    "max_records": 5000,
    "max_response_bytes": 8388608,
    "max_run_seconds": 60
  },
  "retry": {
    "max_attempts": 4,
    "base_delay_ms": 1000,
    "max_retry_after_seconds": 60
  }
}

{
  "version": 1,
  "id": "github_members",
  "name": "GitHub OWASP org public members (live)",
  "request": {
    "method": "GET",
    "url": "https://api.github.com/orgs/owasp/members",
    "timeout_seconds": 20,
    "params": {
      "per_page": "10"
    },
    "headers": {
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28"
    }
  },
  "auth": {
    "type": "bearer",
    "secret": "github_token"
  },
  "items_path": "",
  "pagination": {
    "type": "link"
  },
  "schedule": {
    "enabled": false,
    "interval_seconds": 3600
  },
  "destination": {
    "class": "user_inventory",
    "mapping": {
      "user.uid": {
        "path": "id",
        "required": true,
        "transform": "string"
      },
      "user.name": {
        "path": "login",
        "transform": "string"
      },
      "user.type_id": {
        "path": "site_admin",
        "transform": "lookup",
        "lookup": {
          "true": "2",
          "false": "1"
        }
      },
      "metadata.product.name": {
        "constant": "GitHub"
      },
      "metadata.product.vendor_name": {
        "constant": "GitHub"
      }
    }
  },
  "limits": {
    "max_pages": 10,
    "max_records": 500,
    "max_response_bytes": 1048576,
    "max_run_seconds": 60
  },
  "retry": {
    "max_attempts": 4,
    "base_delay_ms": 1000,
    "max_retry_after_seconds": 60
  }
}

